# Create mode() function to calculate mode
mode <- function(x, na.rm = FALSE) {

  if(na.rm){ #if na.rm is TRUE, remove NA values from input x
    x = x[!is.na(x)]
  }

  val <- unique(x)
  return(val[which.max(tabulate(match(x, val)))])
}
